func (this *Table) SetItemCount(count int32) {
	this.CheckWidget()
	count = int32(math.Max(float64(0), float64(count)))
	if count == this.itemCount {
		return
	}
	var isVirtual bool = (this.style & VIRTUAL) != 0
	if !isVirtual {
		this.impl.setRedraw_(false)
	}
	this.RemoveStartEnd(count, this.itemCount-1)
	var length int32 = int32(math.Max(float64(4), float64((count+3)/4*4)))
	var newItems []*TableItem = make([]*TableItem, length)
	copy(newItems[0:], this.items[0:0+this.itemCount])
	this.items = newItems
	if isVirtual {
		var iter int64 = gtk.OSG_malloc(int64(gtk.GTKGtkTreeIter_sizeof()))
		if iter == 0 {
			this.Error(ERROR_NO_HANDLES)
		}
		for i := int32(this.itemCount); i < count; i++ {
			gtk.GTKGtk_list_store_append(this.modelHandle, iter)
		}
		gtk.OSG_free(iter)
		this.itemCount = count
	} else {
		for i := int32(this.itemCount); i < count; i++ {
			newTableItemParentStyleIndexCreate(this, NONE, i, true)
		}
	}
	if !isVirtual {
		this.impl.setRedraw_(true)
	}
}

func (this *Table) SetLinesVisible(show bool) {
	this.CheckWidget()
	var cond495 int32
	if show {
		cond495 = gtk.GTKGTK_TREE_VIEW_GRID_LINES_VERTICAL
	} else {
		cond495 = gtk.GTKGTK_TREE_VIEW_GRID_LINES_NONE
	}
	gtk.GTKGtk_tree_view_set_grid_lines(this.Handle, cond495)
}

func (this *Table) SetModel(newModel int64) {
	this.display.RemoveWidget(this.modelHandle)
	gtk.OSG_object_unref(this.modelHandle)
	this.modelHandle = newModel
	this.display.AddWidget(this.modelHandle, upcastTableToWidget(this))
}

