func (this *Table) setRedraw_(redraw bool) {
	this.CheckWidget()
	this.Composite.setRedraw_(redraw)
	if redraw && this.drawCount == 0 {
		if int32(len(this.items)) > 4 && int32(len(this.items))-this.itemCount > 3 {
			var length int32 = int32(math.Max(float64(4), float64((this.itemCount+3)/4*4)))
			var newItems []*TableItem = make([]*TableItem, length)
			copy(newItems[0:], this.items[0:0+this.itemCount])
			this.items = newItems
		}
	}
}

func (this *Table) SetScrollWidthLocal1(column int64, itemLike TableItemLike) {
	var item *TableItem
	if itemLike != nil {
		item = itemLike.AsTableItem()
	}
	_ = item
	if this.columnCount != 0 || this.currentItem == item {
		return
	}
	var width int32 = gtk.GTKGtk_tree_view_column_get_fixed_width(column)
	var itemWidth int32 = this.CalculateWidth(column, item.Handle)
	if width < itemWidth {
		gtk.GTKGtk_tree_view_column_set_fixed_width(column, itemWidth)
	}
}
